-- Seed Bimbel maddah for Fakultas Syari'ah (Tingkat 1-4) and Ushuluddin (Tingkat 1-2),
-- plus one "Paket Lengkap" bundle per fakultas + tingkat (requires 20261006000100_bimbel_bundles).
-- Every row is an unpublished draft with price 0 and no lessons yet: admin sets the price,
-- PJ, WhatsApp group / PDF muqorror links, and YouTube recordings, then publishes.
-- Idempotent: existing slugs are left untouched so admin edits are never overwritten.

insert into public.courses (
  slug,
  title,
  program_type,
  faculty,
  summary,
  tutor,
  schedule,
  duration,
  price,
  is_published,
  media_format,
  has_certificate,
  tingkat,
  is_bundle
)
